// Paquets de modèles Tesseract (fichiers .traineddata.gz locaux) : seul `langPath` est utilisé.
declare module "@tesseract.js-data/fra" { const data: { code: string; gzip: boolean; langPath: string }; export default data }
declare module "@tesseract.js-data/eng" { const data: { code: string; gzip: boolean; langPath: string }; export default data }
